/// Raven `Pickup_Team`.
///
/// Source: `oracle/oracle/codemp/game/g_team.c:848-871`
pub fn Pickup_Team(
    ent: *mut gentity_t,
    other: *mut gentity_t,
) -> c_int {
    unsafe {
        let classname = CStr::from_ptr((*ent).classname);
        let team = if classname == c"team_CTF_redflag" {
            TEAM_RED
        } else if classname == c"team_CTF_blueflag" {
            TEAM_BLUE
        } else if classname == c"team_CTF_neutralflag" {
            TEAM_FREE
        } else {
            // PrintMsg(other, "Don't know what team the flag is on.\n") — dead.
            return 0;
        };

        let cl = (*other).client as *mut gclient_t;
        if team == (*cl).sess.sessionTeam as c_int {
            Team_TouchOurFlag(ent, other, team)
        } else {
            Team_TouchEnemyFlag(ent, other, team)
        }
    }
}

